//! Where an export is allowed to land, and how it gets there (spec 16.5).
//!
//! Two rules make a hostile recording title harmless:
//!
//! 1. The *directory* comes from an operating-system file picker and is
//!    canonicalized once, here. Nothing else may supply a directory.
//! 2. The *file name* is generated by us. A title contributes at most a
//!    sanitized slug; separators, traversal, control characters, reserved
//!    Windows device names and trailing dots/spaces cannot survive it.
//!
//! Writes are atomic: bytes land in a private temporary file beside the
//! target, are flushed, and are then renamed over the target. An interrupted
//! export therefore leaves either the previous file or nothing, never a
//! half-written export.

use std::fs::{File, OpenOptions};
use std::io::Write;
use std::path::{Component, Path, PathBuf};

use uuid::Uuid;

use crate::error::{ExportError, ExportResult};

/// Longest slug we take from a user-supplied title.
pub const MAX_SLUG_CHARS: usize = 80;

/// Names Windows refuses as file names, in any case and with any extension.
const RESERVED_STEMS: &[&str] = &[
    "con", "prn", "aux", "nul", "com1", "com2", "com3", "com4", "com5", "com6", "com7", "com8",
    "com9", "lpt1", "lpt2", "lpt3", "lpt4", "lpt5", "lpt6", "lpt7", "lpt8", "lpt9",
];

/// Reduce arbitrary user text to a file-name-safe slug.
///
/// The result contains only ASCII alphanumerics, space, `.`, `_` and `-`; it
/// never starts with `.` or `-`, never ends with `.` or a space, is never a
/// reserved Windows device name, and is never empty.
#[must_use]
pub fn sanitize_slug(raw: &str) -> String {
    let mut out = String::with_capacity(raw.len().min(MAX_SLUG_CHARS));
    let mut last_was_space = false;
    for ch in raw.chars() {
        let mapped = match ch {
            'a'..='z' | 'A'..='Z' | '0'..='9' | '.' | '_' | '-' => ch,
            ' ' | '\t' | '\n' | '\r' => ' ',
            _ => '-',
        };
        if mapped == ' ' {
            if last_was_space || out.is_empty() {
                continue;
            }
            last_was_space = true;
        } else {
            last_was_space = false;
        }
        out.push(mapped);
        if out.chars().count() >= MAX_SLUG_CHARS {
            break;
        }
    }
    // Collapse runs of '-' introduced by stripped characters.
    let mut collapsed = String::with_capacity(out.len());
    let mut previous_dash = false;
    for ch in out.chars() {
        if ch == '-' {
            if previous_dash {
                continue;
            }
            previous_dash = true;
        } else {
            previous_dash = false;
        }
        collapsed.push(ch);
    }
    let trimmed = collapsed
        .trim_matches(|c: char| c == ' ' || c == '.' || c == '-')
        .to_owned();
    let stem_is_reserved = trimmed
        .split('.')
        .next()
        .is_some_and(|stem| RESERVED_STEMS.contains(&stem.to_ascii_lowercase().as_str()));
    if trimmed.is_empty() || stem_is_reserved {
        return "recording".to_owned();
    }
    trimmed
}

/// A validated directory an export may be written into.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ExportDestination {
    directory: PathBuf,
}

impl ExportDestination {
    /// Validate a user-selected directory.
    ///
    /// The directory must already exist and resolve to a directory after
    /// symlink resolution. We deliberately accept a symlinked directory the
    /// user picked themselves — it is their choice — but we resolve it once
    /// and pin every later write to the resolved location, so a path swapped
    /// underneath us cannot redirect a write.
    pub fn new(directory: impl AsRef<Path>) -> ExportResult<Self> {
        let raw = directory.as_ref();
        if raw.as_os_str().is_empty() {
            return Err(ExportError::DestinationRejected(
                "no folder was selected".into(),
            ));
        }
        let canonical = std::fs::canonicalize(raw).map_err(|error| {
            ExportError::DestinationRejected(format!(
                "the folder could not be opened ({})",
                error.kind()
            ))
        })?;
        if !canonical.is_dir() {
            return Err(ExportError::DestinationRejected(
                "the selected path is not a folder".into(),
            ));
        }
        Ok(Self {
            directory: canonical,
        })
    }

    /// The resolved directory.
    #[must_use]
    pub fn directory(&self) -> &Path {
        &self.directory
    }

    /// A short hint suitable for `export_events.destination_hint`.
    ///
    /// Spec 13.2 keeps complete sensitive paths out of the database, so this
    /// is the final directory component only.
    #[must_use]
    pub fn hint(&self) -> String {
        self.directory
            .file_name()
            .map_or_else(|| "selected folder".to_owned(), |n| n.to_string_lossy().into_owned())
    }

    /// Resolve a generated file name inside this destination.
    ///
    /// The name is sanitized again here, so no caller can smuggle a separator
    /// through, and the result is asserted to be a direct child.
    pub fn resolve(&self, file_name: &str) -> ExportResult<PathBuf> {
        let safe = sanitize_slug(file_name);
        let candidate = self.directory.join(&safe);
        let is_direct_child = candidate.parent() == Some(self.directory.as_path())
            && Path::new(&safe)
                .components()
                .all(|c| matches!(c, Component::Normal(_)))
            && Path::new(&safe).components().count() == 1;
        if !is_direct_child {
            return Err(ExportError::DestinationRejected(format!(
                "the generated file name is not a direct child of the folder: {safe}"
            )));
        }
        Ok(candidate)
    }

    /// Write `bytes` atomically to `file_name` inside this destination.
    pub fn write_atomic(&self, file_name: &str, bytes: &[u8]) -> ExportResult<PathBuf> {
        self.write_atomic_with(file_name, |file| {
            file.write_all(bytes)?;
            Ok(bytes.len() as u64)
        })
    }

    /// Stream into `file_name` atomically.
    ///
    /// `fill` receives the temporary file and returns the number of bytes it
    /// wrote. Any error, including a panic-free early return, removes the
    /// temporary file and leaves the destination untouched.
    pub fn write_atomic_with<F>(&self, file_name: &str, fill: F) -> ExportResult<PathBuf>
    where
        F: FnOnce(&mut File) -> ExportResult<u64>,
    {
        let target = self.resolve(file_name)?;
        self.reject_unsafe_target(&target)?;
        let temporary = self
            .directory
            .join(format!(".plaudon-export-{}.part", Uuid::now_v7()));
        let mut file = OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&temporary)?;
        let outcome = fill(&mut file).and_then(|written| {
            file.flush()?;
            file.sync_all()?;
            Ok(written)
        });
        drop(file);
        if let Err(error) = outcome {
            let _ = std::fs::remove_file(&temporary);
            return Err(error);
        }
        if let Err(error) = std::fs::rename(&temporary, &target) {
            let _ = std::fs::remove_file(&temporary);
            return Err(ExportError::Io(error));
        }
        sync_directory(&self.directory);
        Ok(target)
    }

    /// Refuse to overwrite anything that is not a plain file we can replace.
    ///
    /// A symlink at the target would make the rename replace the link rather
    /// than its target on POSIX, but a pre-existing symlink is still a signal
    /// that the destination is not what the user thinks it is.
    fn reject_unsafe_target(&self, target: &Path) -> ExportResult<()> {
        match std::fs::symlink_metadata(target) {
            Ok(metadata) if metadata.file_type().is_symlink() => {
                Err(ExportError::DestinationRejected(
                    "a symbolic link already exists at that name".into(),
                ))
            }
            Ok(metadata) if !metadata.is_file() => Err(ExportError::DestinationRejected(
                "a folder or special file already exists at that name".into(),
            )),
            _ => Ok(()),
        }
    }
}

/// Best-effort directory flush so a rename survives a power loss.
///
/// Windows has no directory handle to flush; the rename is already ordered.
pub(crate) fn sync_directory(path: &Path) {
    #[cfg(unix)]
    if let Ok(dir) = File::open(path) {
        let _ = dir.sync_all();
    }
    #[cfg(not(unix))]
    let _ = path;
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn traversal_and_separators_cannot_survive_a_title() {
        for hostile in [
            "../../etc/passwd",
            "..\\..\\windows\\system32",
            "/etc/shadow",
            "a/b",
            "a\0b",
            "\u{202e}gnp.exe",
        ] {
            let slug = sanitize_slug(hostile);
            assert!(!slug.contains('/'), "{hostile} -> {slug}");
            assert!(!slug.contains('\\'), "{hostile} -> {slug}");
            assert!(!slug.contains('\0'), "{hostile} -> {slug}");
            assert!(!slug.starts_with('.'), "{hostile} -> {slug}");
            assert_eq!(Path::new(&slug).components().count(), 1, "{hostile}");
        }
    }

    #[test]
    fn reserved_windows_names_and_empty_titles_become_a_safe_default() {
        assert_eq!(sanitize_slug("CON"), "recording");
        assert_eq!(sanitize_slug("nul.txt"), "recording");
        assert_eq!(sanitize_slug("   "), "recording");
        assert_eq!(sanitize_slug("..."), "recording");
        assert_eq!(sanitize_slug("***"), "recording");
    }

    #[test]
    fn a_slug_is_bounded_and_keeps_readable_text() {
        assert_eq!(sanitize_slug("Weekly sync: Q3  plan"), "Weekly sync- Q3 plan");
        let long = "x".repeat(500);
        assert!(sanitize_slug(&long).chars().count() <= MAX_SLUG_CHARS);
    }

    #[test]
    fn a_slug_never_ends_with_a_dot_or_space() {
        for raw in ["trailing.", "trailing ", "trailing. ", "trailing..."] {
            let slug = sanitize_slug(raw);
            assert!(!slug.ends_with('.'), "{raw} -> {slug}");
            assert!(!slug.ends_with(' '), "{raw} -> {slug}");
        }
    }

    #[test]
    fn a_missing_directory_is_rejected_rather_than_created() {
        let dir = tempfile::tempdir().unwrap();
        let error = ExportDestination::new(dir.path().join("absent")).unwrap_err();
        assert!(matches!(error, ExportError::DestinationRejected(_)));
        assert!(!dir.path().join("absent").exists());
    }

    #[test]
    fn a_file_is_not_a_destination() {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("file.txt");
        std::fs::write(&file, b"x").unwrap();
        assert!(ExportDestination::new(&file).is_err());
    }

    #[test]
    fn an_atomic_write_leaves_no_partial_file_on_failure() {
        let dir = tempfile::tempdir().unwrap();
        let destination = ExportDestination::new(dir.path()).unwrap();
        let error = destination
            .write_atomic_with("notes.txt", |file| {
                file.write_all(b"half")?;
                Err(ExportError::IntegrityFailed)
            })
            .unwrap_err();
        assert!(matches!(error, ExportError::IntegrityFailed));
        let remaining: Vec<_> = std::fs::read_dir(dir.path())
            .unwrap()
            .map(|e| e.unwrap().file_name())
            .collect();
        assert!(remaining.is_empty(), "left behind {remaining:?}");
    }

    #[test]
    fn an_atomic_write_replaces_the_previous_export() {
        let dir = tempfile::tempdir().unwrap();
        let destination = ExportDestination::new(dir.path()).unwrap();
        destination.write_atomic("notes.txt", b"first").unwrap();
        let path = destination.write_atomic("notes.txt", b"second").unwrap();
        assert_eq!(std::fs::read(&path).unwrap(), b"second");
        let entries: Vec<_> = std::fs::read_dir(dir.path()).unwrap().collect();
        assert_eq!(entries.len(), 1, "no temporary file may remain");
    }

    #[cfg(unix)]
    #[test]
    fn a_symlinked_target_name_is_refused() {
        let dir = tempfile::tempdir().unwrap();
        let outside = tempfile::tempdir().unwrap();
        let victim = outside.path().join("victim.txt");
        std::fs::write(&victim, b"original").unwrap();
        std::os::unix::fs::symlink(&victim, dir.path().join("notes.txt")).unwrap();

        let destination = ExportDestination::new(dir.path()).unwrap();
        let error = destination.write_atomic("notes.txt", b"attack").unwrap_err();
        assert!(matches!(error, ExportError::DestinationRejected(_)));
        assert_eq!(std::fs::read(&victim).unwrap(), b"original");
    }
}
